import Foundation

// The files the server reads, generated from this module by `scripts/generate-health-cards`, and
// kept fresh by `scripts/format` (`--lint` fails when one is stale), as health-catalog.json is.

extension HealthCards {
  /// The generated files, by path from the repository's root, with their contents.
  static func generatedFiles() -> [(path: String, contents: String)] {
    [
      ("Services/api/card-spec.schema.json", specSchema.text(pretty: true) + "\n"),
      ("Services/api/card-seed.json", seedJSON.text(pretty: true) + "\n"),
      (
        "Services/api/test/health/cards/validation-cases.json",
        validationCasesJSON.text(pretty: true) + "\n"
      ),
    ]
  }

  /// `Services/api/card-seed.json`: the welcome seed's rows, but for their times, which the store
  /// sets when it seeds.
  static var seedJSON: CardJSON {
    [
      "description": .string(
        "The welcome seed (docs/decisions/cards.md): the health_card rows every store starts "
          + "with, but for createdAt and updatedAt. Generated from HealthCards.welcomeSeed by "
          + "scripts/generate-health-cards: don't edit."),
      "cards": .array(
        welcomeSeed.map {
          [
            "id": .string($0.id), "seed": .string($0.seed), "position": .string($0.position),
            "spec": $0.spec.json,
          ]
        }),
    ]
  }

  /// `Services/api/test/health/cards/validation-cases.json`: what the validator and positions
  /// give for each case, which the server's port must give too, word for word.
  static var validationCasesJSON: CardJSON {
    let specs: [CardJSON] = CardValidationCases.specs.map { item in
      var members: [(key: String, value: CardJSON)] = [
        ("name", .string(item.name)), ("mode", .string(item.mode.rawValue)), ("spec", item.spec),
      ]
      switch item.mode {
      case .input:
        switch Result(catching: { () throws(CardSpecValidationError) in
          try CardSpec(input: item.spec)
        }) {
        case .success(let spec): members.append(("canonical", spec.json))
        case .failure(let error): members.append(("errors", errorsJSON(error.errors)))
        }
      case .stored:
        members.append(("errors", errorsJSON(CardSpec.storedErrors(item.spec))))
      }
      return .object(members)
    }

    func position(_ value: String?) -> CardJSON { value.map(CardJSON.string) ?? .null }
    let between: [CardJSON] = CardValidationCases.between.map { a, b in
      [
        "a": position(a), "b": position(b),
        "position": position(try? CardPosition.between(a, b)),
      ]
    }
    let betweenCount: [CardJSON] = CardValidationCases.betweenCount.map { a, b, count in
      [
        "a": position(a), "b": position(b), "count": .number(Double(count)),
        "positions": (try? CardPosition.between(a, b, count: count))
          .map { .array($0.map(CardJSON.string)) } ?? .null,
      ]
    }
    let validity: [CardJSON] = CardValidationCases.positions.map { value in
      [
        "position": .string(value),
        "error": CardPosition.error(value).map(errorJSON) ?? .null,
      ]
    }

    return [
      "description": .string(
        "Card spec validation (docs/decisions/cards.md, Validation and errors) and positions "
          + "(fractional indexing), as the Swift HealthCards module gives them. The server's "
          + "port must give the same, errors in the same order, word for word. Mode \"input\" "
          + "canonicalizes (CardSpec(input:)): the canonical form, or the errors. Mode "
          + "\"stored\" is the store's check (CardSpec.storedErrors). \"between\" gives null "
          + "where it throws. Generated by scripts/generate-health-cards from "
          + "CardValidationCases: don't edit."),
      "specs": .array(specs),
      "positions": [
        "between": .array(between), "betweenCount": .array(betweenCount),
        "validity": .array(validity),
      ],
    ]
  }

  private static func errorsJSON(_ errors: [CardSpecError]) -> CardJSON {
    .array(errors.map(errorJSON))
  }

  private static func errorJSON(_ error: CardSpecError) -> CardJSON {
    [
      "path": .string(error.path), "code": .string(error.code.rawValue),
      "message": .string(error.message),
    ]
  }
}
